WITH unpivoted AS (SELECT * FROM (SELECT id, category, price, cost FROM products) src UNPIVOT (reading FOR kpi IN (price, cost))) SELECT CASE WHEN reading >= 87 THEN 'PREMIUM' ELSE 'STANDARD' END AS reading_tier, SORT_ARRAY(COLLECT_SET(kpi)) AS kpi_list, APPROX_PERCENTILE(reading, ARRAY(0.25, 0.5, 0.75)) AS reading_quartiles, SUM(reading) AS total_reading, MAX(reading) FILTER (WHERE kpi = 'cost') AS cost_max_reading, SORT_ARRAY(COLLECT_SET(category)) AS category_list, COUNT_IF(category = 'Electronics') AS electronics_events FROM unpivoted GROUP BY CASE WHEN reading >= 87 THEN 'PREMIUM' ELSE 'STANDARD' END
